package com.mediassistrover.backend;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.mediassistrover.backend.ai.*;
import com.mediassistrover.backend.entity.*;
import com.mediassistrover.backend.enums.*;
import com.mediassistrover.backend.mqtt.*;
import com.mediassistrover.backend.repository.*;
import com.mediassistrover.backend.security.*;
import com.mediassistrover.backend.service.*;
import com.mediassistrover.backend.dto.monitoring.request.MonitoringRequests.*;
import com.mediassistrover.backend.dto.pi.request.PiEnvelope;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.annotation.DirtiesContext;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

@DirtiesContext(classMode=DirtiesContext.ClassMode.AFTER_CLASS)
class AiMonitoringIntegrationTest extends MySqlIntegrationTest {
    @Autowired ObjectMapper json;@Autowired MqttWire wire;@Autowired MqttProperties mqtt;@Autowired AiProperties properties;@Autowired AiSensingService ai;
    @Autowired MqttConnectionState connection;@Autowired MqttInboundRouter router;@Autowired MqttDurablePublisher publisher;@Autowired MqttPublicationPlans plans;
    @Autowired WorkflowOrchestratorService orchestrator;@Autowired OrchestrationWorkService work;@Autowired MonitoringService monitoring;
    @Autowired JobRepository jobs;@Autowired JobStepRepository steps;@Autowired RobotRepository robots;@Autowired AccountRepository accounts;
    @Autowired RobotCommandOutboxRepository commands;@Autowired AiObservationRepository observations;@Autowired AiSensingProfileRepository profiles;
    @Autowired CrowdDensityRecordRepository crowd;@Autowired DetectionEventRepository detections;@Autowired HeatmapRecordRepository heatmaps;
    @Autowired MonitoringIngestionReceiptRepository receipts;@Autowired ZoneRepository zones;
    @Autowired org.springframework.test.web.servlet.MockMvc mvc;@Autowired JwtTokenService tokens;@Autowired DeviceJwtTokenService deviceTokens;
    @Autowired PlatformTransactionManager tm;@Autowired jakarta.persistence.EntityManager em;
    @MockitoBean PahoMqttTransport transport;
    TransactionTemplate tx;MqttTestFixture f;UUID zoneId;String sensing;long restSequence;ObjectNode original;int windowSec;
    @BeforeEach void setup(){tx=new TransactionTemplate(tm);mqtt.setEnabled(true);mqtt.setDispatchEnabled(true);mqtt.setAllowSimulation(true);mqtt.getRobotIds().clear();mqtt.setEnabledStepTypes(new HashSet<>(Set.of("EXECUTE_SENSING","WAIT","MOVE")));properties.setSensingEnabled(true);connection.connectedNow();when(transport.connected()).thenReturn(true);when(transport.publish(anyString(),any(byte[].class),anyInt())).thenReturn(CompletableFuture.completedFuture(null));}
    @AfterEach void cleanup(){if(f!=null)tx.executeWithoutResult(s->{
        em.createNativeQuery("DELETE FROM AiObservation WHERE robot_id=:id").setParameter("id",f.robotId).executeUpdate();
        em.createNativeQuery("DELETE FROM CrowdDensityRecord WHERE robot_id=:id").setParameter("id",f.robotId).executeUpdate();
        em.createNativeQuery("DELETE FROM DetectionEvent WHERE robot_id=:id").setParameter("id",f.robotId).executeUpdate();
        em.createNativeQuery("DELETE FROM MonitoringIngestionReceipt WHERE robot_id=:id").setParameter("id",f.robotId).executeUpdate();
        em.createNativeQuery("DELETE FROM AiSensingProfile WHERE robot_id=:id").setParameter("id",f.robotId).executeUpdate();
        em.createNativeQuery("DELETE FROM HeatmapRecord WHERE map_id=:id").setParameter("id",f.mapId).executeUpdate();
        em.createNativeQuery("DELETE FROM AuditLog WHERE account_id=:id").setParameter("id",f.accountId).executeUpdate();
        em.createNativeQuery("DELETE FROM Zone WHERE map_id=:id").setParameter("id",f.mapId).executeUpdate();MqttTestFixture.cleanup(em,f);
    });mqtt.setEnabled(false);mqtt.setDispatchEnabled(false);mqtt.getRobotIds().clear();properties.setSensingEnabled(false);connection.disconnected();}
    void fixture(String type,boolean configured){sensing=type;
        f=tx.execute(s->{var fixture=MqttTestFixture.create(em,json,StepType.MOVE,null);fixture.type=StepType.EXECUTE_SENSING;fixture.sensing=type;
            JobStep step=steps.findById(fixture.piStepId).orElseThrow();step.setStepTypeSnapshot("EXECUTE_SENSING");step.getStep().setStepType(StepType.EXECUTE_SENSING);Job job=step.getJobTask().getJob();job.getRobot().setDeviceSecretHash("test-only");
            var zone=zones.saveAndFlush(Zone.builder().map(job.getMap()).zoneCode("AI-"+UUID.randomUUID()).zoneName("Test AI zone").zoneType(type.equals("RESTRICTED_ZONE")?ZoneType.KEEP_OUT:ZoneType.NO_STOP).active(true).polygonJson(json.createArrayNode()).build());zoneId=zone.getZoneId();
            step.getStep().setParamsJson(json.createObjectNode().put("sensing_type",type).put("zone_id",zoneId.toString()).put("window_sec",windowSec));return fixture;});
        mqtt.getRobotIds().add(f.robotId);if(configured)configure("model-1",true,false);advance();receive(f.hello(json));heartbeat();if(configured)advance();}
    void configure(String model,boolean enabled,boolean positions){ai.configure(f.robotId,new AiSensingService.Configure(zoneId,sensing,model,"camera-A",enabled,positions,"Test fixture commissioning; no real producer"),actor());}
    AccountPrincipal actor(){return AccountPrincipal.fromAccount(accounts.findById(f.accountId).orElseThrow());}
    DevicePrincipal device(){var robot=robots.findById(f.robotId).orElseThrow();return new DevicePrincipal(robot.getRobotId(),robot.getRobotCode(),robot.getDeviceTokenVersion(),"test",Instant.now().plusSeconds(600));}
    void advance(){tx.executeWithoutResult(s->work.request(jobs.findById(f.jobId).orElseThrow()));orchestrator.advance(f.jobId);}
    void receive(ObjectNode event){router.route(MqttTopics.topic(f.robotId,"events"),wire.bytes(event),1,false);}
    void heartbeat(){router.route(MqttTopics.topic(f.robotId,"heartbeat"),wire.bytes(f.heartbeat(json)),0,false);}
    void issue(){tx.executeWithoutResult(s->{var step=em.find(Job.class,f.jobId).getSelectedJobStep();f.piStepId=step.getJobStepId();f.operationKey=step.getOperationKey();});var command=commands.findByJobStepId(f.piStepId).orElseThrow();f.commandId=command.getCommandId();publisher.command(f.commandId);}
    void start(){receive(f.event(json,"COMMAND_ACK",json.createObjectNode().put("commandId",f.commandId.toString()).put("commandType","EXECUTE_STEP").put("accepted",true).put("status","ACCEPTED")));
        receive(f.event(json,"STEP_STARTED",json.createObjectNode().put("stepType","EXECUTE_SENSING").put("attemptNo",1).set("resolvedInputs",commands.findById(f.commandId).orElseThrow().getPayloadJson().path("step").path("params"))));}
    ObjectNode output(){var result=json.createObjectNode().put("sensing_type",sensing).put("map_id",f.mapId.toString()).put("zone_id",zoneId.toString()).put("model_version","model-1").put("captured_at",Instant.now().toString()).putNull("evidence_ref");var metrics=result.putObject("metrics");if(sensing.equals("CROWD_DENSITY"))metrics.put("count",7);else metrics.put("intrusion_detected",true);return result;}
    ObjectNode result(ObjectNode output){return f.event(json,"STEP_RESULT",json.createObjectNode().put("status","SUCCEEDED").put("retryable",false).put("physicalStopConfirmed",true).putNull("details").putNull("errorCode").set("result",output));}
    JobStatus status(){return jobs.findById(f.jobId).orElseThrow().getStatus();}
    <T> PiEnvelope<T> rest(UUID id,String type,T payload){return new PiEnvelope<>("1.0",id,"rest:"+id,id,f.robotId,null,null,type,Instant.now(),f.producerId,++restSequence,payload);}
    DetectionPayload detection(Instant at,BigDecimal x,BigDecimal y,String track){return new DetectionPayload(f.mapId,zoneId,DetectionEventType.OTHER,null,x,y,DetectionLocationBasis.OBJECT,"model-1",json.createObjectNode().put("contract","BE-PERSON-POSITION-1").put("producer_ref","camera-A").put("frame_id","map").put("track_id",track),null,at);}

    @Test void crowdResultIsPersistedInTheCompletionTransactionAndDuplicateOnlyAcknowledged(){fixture("CROWD_DENSITY",true);issue();start();var output=output();var event=result(output);receive(event);assertThat(observations.count()).isEqualTo(1);assertThat(crowd.findAll()).hasSize(1);assertThat(crowd.findAll().getFirst().getPersonCount()).isEqualTo(7);assertThat(crowd.findAll().getFirst().getDensityLevel()).isNull();receive(event);assertThat(crowd.count()).isEqualTo(1);advance();advance();advance();assertThat(status()).isEqualTo(JobStatus.SUCCEEDED);}
    @Test void restrictedIntrusionCreatesDetectionWithoutFabricatedPositionOrIncident(){fixture("RESTRICTED_ZONE",true);issue();start();receive(result(output()));var event=detections.findAll().getFirst();assertThat(event.getEventType()).isEqualTo(DetectionEventType.RESTRICTED_INTRUSION);assertThat(event.getLocationBasis()).isEqualTo(DetectionLocationBasis.UNKNOWN);assertThat(event.getXM()).isNull();assertThat(observations.count()).isEqualTo(1);}
    @Test void falseIntrusionStillPersistsObservationButNoPositiveDetection(){fixture("RESTRICTED_ZONE",true);issue();start();var output=output();((ObjectNode)output.path("metrics")).put("intrusion_detected",false);receive(result(output));assertThat(observations.count()).isEqualTo(1);assertThat(detections.count()).isZero();assertThat(steps.findById(f.piStepId).orElseThrow().getStatus()).isEqualTo(JobStepStatus.SUCCEEDED);}
    @Test void dispatchRequiresAnExplicitCommissionedProfile(){fixture("CROWD_DENSITY",false);assertThatThrownBy(this::advance).hasMessageContaining("not commissioned");assertThat(commands.findByJobStepId(f.piStepId)).isEmpty();}
    @Test void disabledAiCannotDispatchOrPublish(){fixture("CROWD_DENSITY",true);properties.setSensingEnabled(false);assertThat(plans.command(commands.findByJobStepId(f.piStepId).orElseThrow().getCommandId())).isNull();assertThat(observations.count()).isZero();}
    @Test void changedProfileBeforeFirstPublishDoesNotChangeFrozenOperation(){fixture("CROWD_DENSITY",true);var command=commands.findByJobStepId(f.piStepId).orElseThrow();var before=command.getPayloadJson().deepCopy();configure("model-2",true,false);assertThat(plans.command(command.getCommandId())).isNull();assertThat(commands.findById(command.getCommandId()).orElseThrow().getPayloadJson()).isEqualTo(before);}
    @Test void resultUsesModelSnapshotAfterAdminChangesConfig(){fixture("CROWD_DENSITY",true);issue();start();configure("model-2",true,false);receive(result(output()));assertThat(observations.count()).isEqualTo(1);assertThat(crowd.findAll().getFirst().getModelVersion()).isEqualTo("model-1");}
    @Test void wrongModelRollsBackMonitoring(){fixture("CROWD_DENSITY",true);issue();start();var output=output().put("model_version","wrong");receive(result(output));assertThat(status()).isEqualTo(JobStatus.RECOVERY_REQUIRED);assertThat(observations.count()).isZero();assertThat(crowd.count()).isZero();assertThat(steps.findById(f.piStepId).orElseThrow().getStatus()).isEqualTo(JobStepStatus.RUNNING);}
    @Test void staleObservationIsRejectedWithoutCompletion(){fixture("CROWD_DENSITY",true);issue();start();receive(result(output().put("captured_at",Instant.now().minusSeconds(3).toString())));assertThat(status()).isEqualTo(JobStatus.RECOVERY_REQUIRED);assertThat(crowd.count()).isZero();}
    @Test void futureObservationIsRejected(){fixture("CROWD_DENSITY",true);issue();start();receive(result(output().put("captured_at",Instant.now().plusSeconds(6).toString())));assertThat(status()).isEqualTo(JobStatus.RECOVERY_REQUIRED);assertThat(crowd.count()).isZero();}
    @Test void freshWindowRejectsObservationBeforeStarted(){windowSec=3;fixture("CROWD_DENSITY",true);issue();start();receive(result(output().put("captured_at",Instant.now().minusSeconds(1).toString())));assertThat(status()).isEqualTo(JobStatus.RECOVERY_REQUIRED);}
    @Test void sameObservationAcrossVisitsIsStoredOnceAndConflictIsRejected(){fixture("CROWD_DENSITY",true);issue();start();original=output();receive(result(original));var command=commands.findById(f.commandId).orElseThrow();tx.executeWithoutResult(s->ai.completed(em.find(JobStep.class,f.piStepId),command,original,Instant.parse(original.path("captured_at").asText())));assertThat(crowd.count()).isEqualTo(1);
        var changed=original.deepCopy();((ObjectNode)changed.path("metrics")).put("count",8);assertThatThrownBy(()->tx.executeWithoutResult(s->ai.completed(em.find(JobStep.class,f.piStepId),command,changed,Instant.parse(original.path("captured_at").asText())))).hasMessageContaining("different content");assertThat(crowd.count()).isEqualTo(1);}
    @Test void excessiveCountIsRejected(){fixture("CROWD_DENSITY",true);issue();start();var result=output();((ObjectNode)result.path("metrics")).put("count",Long.MAX_VALUE);receive(result(result));assertThat(observations.count()).isZero();}
    @Test void changedMapAssetDuringStepCannotReattributeOldObservation(){fixture("CROWD_DENSITY",true);issue();start();tx.executeWithoutResult(s->em.find(FacilityMap.class,f.mapId).setAssetHash("b".repeat(64)));receive(result(output()));assertThat(status()).isEqualTo(JobStatus.RECOVERY_REQUIRED);assertThat(crowd.count()).isZero();}
    @Test void detectionReceiptRejectsChangedBodyAndForeignRobot(){fixture("CROWD_DENSITY",true);var payload=new DetectionPayload(f.mapId,zoneId,DetectionEventType.SUSPECTED_FALL,new BigDecimal("0.9"),null,null,DetectionLocationBasis.ROBOT,"fall-1",json.createObjectNode(),null,Instant.now());var e=rest(UUID.randomUUID(),"DETECTION_EVENT",payload);assertThat(monitoring.recordDetection(e,device()).duplicate()).isFalse();assertThat(monitoring.recordDetection(e,device()).duplicate()).isTrue();
        var changed=new PiEnvelope<>(e.protocolVersion(),e.messageId(),e.operationKey(),e.correlationId(),e.robotId(),null,null,e.messageType(),e.occurredAt(),e.producerSessionId(),e.sequenceNo(),new DetectionPayload(f.mapId,zoneId,DetectionEventType.SUSPECTED_FALL,new BigDecimal("0.1"),null,null,DetectionLocationBasis.ROBOT,"fall-1",json.createObjectNode(),null,payload.detectedAt()));assertThatThrownBy(()->monitoring.recordDetection(changed,device())).hasMessageContaining("different robot/type/content");}
    @Test void restHistoryDoesNotCountAsFreshWorkflowResultAndFutureHistoryIsBlocked(){fixture("CROWD_DENSITY",true);var old=new DetectionPayload(f.mapId,zoneId,DetectionEventType.SUSPECTED_FALL,null,null,null,DetectionLocationBasis.UNKNOWN,"fall-1",json.createObjectNode(),null,Instant.now().minusSeconds(3600));monitoring.recordDetection(rest(UUID.randomUUID(),"DETECTION_EVENT",old),device());assertThat(steps.findById(f.piStepId).orElseThrow().getStatus()).isEqualTo(JobStepStatus.PENDING);assertThat(observations.count()).isZero();
        var future=new DetectionPayload(f.mapId,zoneId,DetectionEventType.OTHER,null,null,null,DetectionLocationBasis.UNKNOWN,"fall-1",json.createObjectNode(),null,Instant.now().plusSeconds(8));assertThatThrownBy(()->monitoring.recordDetection(rest(UUID.randomUUID(),"DETECTION_EVENT",future),device())).hasMessageContaining("timestamp");}
    @Test void heatmapNeedsCommissionedObjectCoordinatesAndDeduplicatesTracks(){fixture("CROWD_DENSITY",true);configure("model-1",true,true);Instant start=Instant.now().minusSeconds(30);UUID a=UUID.randomUUID(),b=UUID.randomUUID(),c=UUID.randomUUID();
        monitoring.recordDetection(rest(a,"DETECTION_EVENT",detection(start.plusSeconds(1),BigDecimal.ONE,BigDecimal.ONE,"track-A")),device());
        monitoring.recordDetection(rest(b,"DETECTION_EVENT",detection(start.plusSeconds(2),new BigDecimal("2"),BigDecimal.ONE,"track-A")),device());
        monitoring.recordDetection(rest(c,"DETECTION_EVENT",detection(start.plusSeconds(2),new BigDecimal("2"),BigDecimal.ONE,"track-B")),device());
        var input=json.createObjectNode().put("frame_id","map");input.putArray("source_detection_ids").add(a.toString()).add(b.toString()).add(c.toString());
        var request=new HeatmapCreate(f.mapId,"PERSON_POSITIONS",start,Instant.now(),BigDecimal.ONE,input,null,BigDecimal.valueOf(2),3);
        var heatmap=monitoring.createHeatmap(request,f.accountId,new RequestMetadata(null,null,null));assertThat(heatmap.gridData().path("unique_tracks").asInt()).isEqualTo(2);assertThat(heatmap.gridData().path("counts").path(1).path(2).asInt()).isEqualTo(2);assertThat(heatmap.gridData().path("counts").path(1).path(1).asInt()).isZero();
        assertThatThrownBy(()->monitoring.createHeatmap(request,f.accountId,new RequestMetadata(null,null,null))).hasMessageContaining("already exists");}
    @Test void robotCoordinatesAndUncommissionedPositionsCannotBecomeHeatmap(){fixture("CROWD_DENSITY",true);assertThatThrownBy(()->monitoring.recordDetection(rest(UUID.randomUUID(),"DETECTION_EVENT",detection(Instant.now(),BigDecimal.ONE,BigDecimal.ONE,"person")),device())).hasMessageContaining("commissioned position");
        var counts=new HeatmapCreate(f.mapId,"CROWD_DENSITY",Instant.now().minusSeconds(1),Instant.now(),BigDecimal.ONE,json.createObjectNode().put("count",7),null,null,1);assertThatThrownBy(()->monitoring.createHeatmap(counts,f.accountId,new RequestMetadata(null,null,null))).hasMessageContaining("person positions");}
    @Test void profileApiRequiresAdminAndPersistsExplicitModelAndSource() throws Exception {fixture("CROWD_DENSITY",true);String token=tokens.issueAccessToken(accounts.findById(f.accountId).orElseThrow()).value();var body=json.valueToTree(new AiSensingService.Configure(zoneId,sensing,"model-2","camera-B",true,false,"Commissioned by test only"));mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.put("/api/v1/admin/monitoring/robots/"+f.robotId+"/ai-profile").header("Authorization","Bearer "+token).contentType("application/json").content(json.writeValueAsBytes(body))).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk()).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$.model_version").value("model-2"));
        mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.put("/api/v1/admin/monitoring/robots/"+f.robotId+"/ai-profile").contentType("application/json").content(json.writeValueAsBytes(body))).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isUnauthorized());}
    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"map_id","zone_id","frame_id","producer_ref","evidence_ref"})
    void rejectsForeignScopeOrEmbeddedEvidence(String field){fixture("CROWD_DENSITY",true);issue();start();var out=output().put(field,switch(field){case "map_id","zone_id"->UUID.randomUUID().toString();case "evidence_ref"->"data:image/png;base64,AAAA";default->"other";});receive(result(out));assertThat(status()).isEqualTo(JobStatus.RECOVERY_REQUIRED);assertThat(observations.count()).isZero();assertThat(crowd.count()).isZero();}
    @Test void cachedObservationInAnotherSelectedVisitCreatesNoSecondMonitoringRecord(){fixture("CROWD_DENSITY",true);tx.executeWithoutResult(s->{var first=em.find(JobStep.class,f.piStepId).getStep();first.setMaxVisits(2);var end=em.find(JobStep.class,f.endStepId).getStep();
        var route=em.createQuery("select t from StepTransition t where t.fromStep.stepId=:id and t.outcome=:outcome",StepTransition.class).setParameter("id",end.getStepId()).setParameter("outcome",TransitionOutcome.SUCCESS).getSingleResult();route.setTerminalStatus(null);route.setToStep(first);});
        issue();start();var output=output().put("captured_at",Instant.now().plusSeconds(1).toString());receive(result(output));UUID originalCommand=f.commandId;advance();advance();advance();advance();issue();assertThat(f.commandId).isNotEqualTo(originalCommand);start();receive(result(output));assertThat(crowd.count()).isEqualTo(1);assertThat(observations.count()).isEqualTo(1);assertThat(steps.findById(f.piStepId).orElseThrow().getStatus()).isEqualTo(JobStepStatus.SUCCEEDED);}
    @Test void legacyDetectionRetryIsComparedBeforeInstallingAReceipt(){fixture("CROWD_DENSITY",true);var p=new DetectionPayload(f.mapId,zoneId,DetectionEventType.SUSPECTED_FALL,new BigDecimal("0.9"),null,null,DetectionLocationBasis.ROBOT,"fall-1",json.createObjectNode(),null,Instant.now());var e=rest(UUID.randomUUID(),"DETECTION_EVENT",p);monitoring.recordDetection(e,device());tx.executeWithoutResult(s->receipts.deleteById(e.messageId()));assertThat(monitoring.recordDetection(e,device()).duplicate()).isTrue();assertThat(detections.count()).isEqualTo(1);assertThat(receipts.findById(e.messageId())).isPresent();}
    @Test void restEnvelopeCannotAttributeMonitoringToAnotherJob(){fixture("CROWD_DENSITY",true);var p=new DetectionPayload(f.mapId,zoneId,DetectionEventType.SUSPECTED_FALL,null,null,null,DetectionLocationBasis.UNKNOWN,"fall-1",json.createObjectNode(),null,Instant.now());var e=rest(UUID.randomUUID(),"DETECTION_EVENT",p);
        var bad=new PiEnvelope<>(e.protocolVersion(),e.messageId(),e.operationKey(),e.correlationId(),e.robotId(),UUID.randomUUID(),f.piStepId,e.messageType(),e.occurredAt(),e.producerSessionId(),e.sequenceNo(),p);assertThatThrownBy(()->monitoring.recordDetection(bad,device())).hasMessageContaining("Job not found");assertThat(detections.count()).isZero();}
    @Test void mapChangeBeforeFirstPublishCannotReuseOldProfile(){fixture("CROWD_DENSITY",true);var command=commands.findByJobStepId(f.piStepId).orElseThrow();tx.executeWithoutResult(s->{em.find(FacilityMap.class,f.mapId).setAssetHash("b".repeat(64));em.find(Robot.class,f.robotId).setMapAssetHash("b".repeat(64));});assertThat(plans.command(command.getCommandId())).isNull();assertThat(commands.findById(command.getCommandId()).orElseThrow().getSendAttempts()).isZero();}
    @Test void personTrackContractRejectsNumericTrackIds(){fixture("CROWD_DENSITY",true);configure("model-1",true,true);var payload=detection(Instant.now(),BigDecimal.ONE,BigDecimal.ONE,"track");((ObjectNode)payload.eventPayload()).put("track_id",1);assertThatThrownBy(()->monitoring.recordDetection(rest(UUID.randomUUID(),"DETECTION_EVENT",payload),device())).hasMessageContaining("commissioned position");assertThat(detections.count()).isZero();}
    @Test void heatmapUsesProvenanceFrozenBeforeProducerConfigWasChanged(){fixture("CROWD_DENSITY",true);configure("model-1",true,true);Instant at=Instant.now();UUID id=UUID.randomUUID();monitoring.recordDetection(rest(id,"DETECTION_EVENT",detection(at,BigDecimal.ONE,BigDecimal.ONE,"track")),device());configure("model-2",false,false);
        var input=json.createObjectNode().put("frame_id","map");input.putArray("source_detection_ids").add(id.toString());var request=new HeatmapCreate(f.mapId,"PERSON_POSITIONS",at.minusSeconds(1),at.plusSeconds(1),BigDecimal.ONE,input,null,BigDecimal.ONE,1);
        assertThat(monitoring.createHeatmap(request,f.accountId,new RequestMetadata(null,null,null)).gridData().path("unique_tracks").asInt()).isEqualTo(1);}
}
